"""Data models for AI intelligence layer and findings enrichment."""

from enum import Enum
from typing import List, Optional
from pydantic import BaseModel, Field, model_validator


class AIConfidenceEnum(str, Enum):
    HIGH = "high"
    MEDIUM = "medium"
    LOW = "low"


class AIStatusEnum(str, Enum):
    SUCCESS = "success"
    UNAVAILABLE = "unavailable"
    FAILED = "failed"
    SKIPPED = "skipped"


class AIFindingEnrichment(BaseModel):
    """Enrichment metadata generated by AI for a tool-verified finding."""
    why_it_matters: str = Field(..., description="Educational explanation of why the vulnerability/issue matters")
    explanation: Optional[str] = Field(default=None, description="Detailed explanation alias")
    impact: str = Field(default="", description="Potential business, security, or technical consequence")
    fix_steps: List[str] = Field(default_factory=list, description="Step-by-step remediation guide")
    code_before: str = Field(default="", description="Sanitized original code snippet")
    code_after: str = Field(default="", description="Remediated code example")
    suggested_code_diff: Optional[str] = Field(default=None, description="Formatted code diff")
    confidence: AIConfidenceEnum = Field(default=AIConfidenceEnum.HIGH, description="AI explanation confidence")
    confidence_score: Optional[float] = Field(default=None, description="Numeric confidence score")
    status: AIStatusEnum = Field(default=AIStatusEnum.SUCCESS, description="AI processing status")
    error_message: Optional[str] = Field(default=None, description="Error message if enrichment failed")

    @model_validator(mode="after")
    def sync_enrichment_fields(self) -> "AIFindingEnrichment":
        if self.explanation is None:
            self.explanation = self.why_it_matters
        if self.why_it_matters is None or self.why_it_matters == "":
            self.why_it_matters = self.explanation or ""
        if self.confidence_score is None:
            conf_map = {"high": 0.95, "medium": 0.8, "low": 0.6}
            self.confidence_score = conf_map.get(str(self.confidence).lower(), 0.8)
        if self.suggested_code_diff is None and (self.code_before or self.code_after):
            if self.code_before and self.code_after:
                self.suggested_code_diff = f"- {self.code_before}\n+ {self.code_after}"
            elif self.code_before:
                self.suggested_code_diff = f"- {self.code_before}"
            elif self.code_after:
                self.suggested_code_diff = f"+ {self.code_after}"
        return self

    model_config = {
        "use_enum_values": True,
    }



class AIContextData(BaseModel):
    """Sanitized context payload constructed for the AI provider."""
    finding_id: str
    title: str
    category: str
    severity: str
    file: str
    line: int
    rule_id: str
    scanner: str
    message: str
    evidence: str
    surrounding_code: str
    project_name: str
    language: str
    frameworks: List[str] = Field(default_factory=list)


class AIExecutionSummary(BaseModel):
    """High-level summary of AI enrichment across a scan run."""
    status: AIStatusEnum
    enriched_count: int = 0
    failed_count: int = 0
    duration_ms: int = 0
    model_used: Optional[str] = None
    error_message: Optional[str] = None

    model_config = {
        "use_enum_values": True,
    }
